export const pyNone = Object.freeze({ type: 'none' });

export function pyInt(value) {
  return { type: 'int', value: BigInt(value) };
}

export function pyFloat(value) {
  return { type: 'float', value: Number(value) };
}

export function pyBool(value) {
  return { type: 'bool', value: Boolean(value) };
}

export function pyString(value) {
  return { type: 'str', value: String(value) };
}

export function typeName(value) {
  if (Array.isArray(value)) {
    return 'list';
  }
  switch (value.type) {
    case 'int':
      return 'int';
    case 'float':
      return 'float';
    case 'bool':
      return 'bool';
    case 'str':
      return 'str';
    case 'none':
      return 'NoneType';
    default:
      return typeof value;
  }
}

export function multiplyByInt(value, multiplier) {
  const factor = BigInt(multiplier);
  if (Array.isArray(value)) {
    throw new TypeError("can't multiply sequence by non-int of type 'list'");
  }
  switch (value.type) {
    case 'int':
      return pyInt(value.value * factor);
    case 'float':
      return pyFloat(value.value * Number(multiplier));
    case 'bool':
      return pyInt((value.value ? 1n : 0n) * factor);
    case 'str':
      return pyString(value.value.repeat(Number(multiplier)));
    case 'none':
      throw new TypeError("unsupported operand type(s) for *: 'NoneType' and 'int'");
    default:
      throw new TypeError(`unsupported operand type(s) for *: '${typeName(value)}' and 'int'`);
  }
}
